import java.time.*;import java.util.*;
abstract class Room{int number;double price;List<Reservation> reservations=new ArrayList<>();Room(int n,double p){number=n;price=p;}abstract double calculatePrice(long d);boolean isAvailable(LocalDate s,LocalDate e){for(Reservation r:reservations)if(!r.cancelled&&s.isBefore(r.end)&&e.isAfter(r.start))return false;return true;}}
class StandardRoom extends Room{StandardRoom(int n){super(n,100);}double calculatePrice(long d){return d*price;}}class DeluxeRoom extends Room{DeluxeRoom(int n){super(n,200);}double calculatePrice(long d){return d*price;}}
class Reservation{Room room;String customer;LocalDate start,end,deadline;boolean cancelled=false;Reservation(Room r,String c,LocalDate s,LocalDate e,LocalDate d){room=r;customer=c;start=s;end=e;deadline=d;}void cancel(LocalDate t){if(cancelled)System.out.println("Already cancelled");else if(t.isAfter(deadline))System.out.println("Cancellation deadline passed");else{cancelled=true;System.out.println("Reservation cancelled");}}}
public class HotelBookingSystem{public static void main(String[] args){Room r=new StandardRoom(101);LocalDate s=LocalDate.of(2027,1,1),e=LocalDate.of(2027,1,5);if(r.isAvailable(s,e)){Reservation x=new Reservation(r,"Customer A",s,e,LocalDate.of(2026,12,30));r.reservations.add(x);long d=java.time.temporal.ChronoUnit.DAYS.between(s,e);System.out.println("Reservation confirmed");System.out.println("Price: $"+r.calculatePrice(d));x.cancel(LocalDate.of(2026,12,29));}LocalDate s2=LocalDate.of(2027,1,3),e2=LocalDate.of(2027,1,7);System.out.println(r.isAvailable(s2,e2)?"Room available":"Room unavailable");}}